class MyHashMap {
    private static final int PAGE_SIZE = 1000;
    private static final int PAGE_COUNT = 1001;
    private final int[][] values;
    private final boolean[][] present;

    public MyHashMap() {
        values = new int[PAGE_COUNT][];
        present = new boolean[PAGE_COUNT][];
    }

    public void put(int key, int value) {
        ensurePage(key);
        int page = key / PAGE_SIZE;
        int offset = key % PAGE_SIZE;
        values[page][offset] = value;
        present[page][offset] = true;
    }

    public int get(int key) {
        int page = key / PAGE_SIZE;
        int offset = key % PAGE_SIZE;
        if (values[page] == null || !present[page][offset]) {
            return -1;
        }
        return values[page][offset];
    }

    public void remove(int key) {
        int page = key / PAGE_SIZE;
        int offset = key % PAGE_SIZE;
        if (values[page] != null) {
            present[page][offset] = false;
        }
    }

    private void ensurePage(int key) {
        int page = key / PAGE_SIZE;
        if (values[page] == null) {
            values[page] = new int[PAGE_SIZE];
            present[page] = new boolean[PAGE_SIZE];
        }
    }
}

class MyHashMap {
    private static final int BUCKET_COUNT = 769;
    private final Node[] buckets;

    public MyHashMap() {
        buckets = new Node[BUCKET_COUNT];
    }

    public void put(int key, int value) {
        int index = hash(key);
        for (Node node = buckets[index]; node != null; node = node.next) {
            if (node.key == key) {
                node.value = value;
                return;
            }
        }
        buckets[index] = new Node(key, value, buckets[index]);
    }

    public int get(int key) {
        int index = hash(key);
        for (Node node = buckets[index]; node != null; node = node.next) {
            if (node.key == key) {
                return node.value;
            }
        }
        return -1;
    }

    public void remove(int key) {
        int index = hash(key);
        Node previous = null;
        Node node = buckets[index];
        while (node != null) {
            if (node.key == key) {
                if (previous == null) {
                    buckets[index] = node.next;
                } else {
                    previous.next = node.next;
                }
                return;
            }
            previous = node;
            node = node.next;
        }
    }

    private int hash(int key) {
        return key % BUCKET_COUNT;
    }

    private static class Node {
        final int key;
        int value;
        Node next;

        Node(int key, int value, Node next) {
            this.key = key;
            this.value = value;
            this.next = next;
        }
    }
}

class MyHashMap {
    private static final int CAPACITY = 20011;
    private final int[] keys;
    private final int[] values;
    private final byte[] state; // 0 = empty, 1 = occupied, 2 = deleted

    public MyHashMap() {
        keys = new int[CAPACITY];
        values = new int[CAPACITY];
        state = new byte[CAPACITY];
    }

    public void put(int key, int value) {
        int slot = findSlotForInsert(key);
        keys[slot] = key;
        values[slot] = value;
        state[slot] = 1;
    }

    public int get(int key) {
        int slot = findExistingSlot(key);
        return slot == -1 ? -1 : values[slot];
    }

    public void remove(int key) {
        int slot = findExistingSlot(key);
        if (slot != -1) {
            state[slot] = 2;
        }
    }

    private int findSlotForInsert(int key) {
        int hash = key % CAPACITY;
        int firstDeleted = -1;
        for (int step = 0; step < CAPACITY; step++) {
            int index = (hash + step) % CAPACITY;
            if (state[index] == 1 && keys[index] == key) {
                return index;
            }
            if (state[index] == 2 && firstDeleted == -1) {
                firstDeleted = index;
            }
            if (state[index] == 0) {
                return firstDeleted == -1 ? index : firstDeleted;
            }
        }
        if (firstDeleted != -1) {
            return firstDeleted;
        }
        throw new IllegalStateException("hash table is full");
    }

    private int findExistingSlot(int key) {
        int hash = key % CAPACITY;
        for (int step = 0; step < CAPACITY; step++) {
            int index = (hash + step) % CAPACITY;
            if (state[index] == 0) {
                return -1;
            }
            if (state[index] == 1 && keys[index] == key) {
                return index;
            }
        }
        return -1;
    }
}

class MyHashMap {
    private static final int CAPACITY = 20011;
    private final int[] keys;
    private final int[] values;
    private final byte[] state; // 0 = empty, 1 = occupied, 2 = deleted

    public MyHashMap() {
        keys = new int[CAPACITY];
        values = new int[CAPACITY];
        state = new byte[CAPACITY];
    }

    public void put(int key, int value) {
        int slot = findSlotForInsert(key);
        keys[slot] = key;
        values[slot] = value;
        state[slot] = 1;
    }

    public int get(int key) {
        int slot = findExistingSlot(key);
        return slot == -1 ? -1 : values[slot];
    }

    public void remove(int key) {
        int slot = findExistingSlot(key);
        if (slot != -1) {
            state[slot] = 2;
        }
    }

    private int findSlotForInsert(int key) {
        int firstDeleted = -1;
        int hash = hash1(key);
        int stepSize = hash2(key);
        for (int step = 0; step < CAPACITY; step++) {
            int index = (hash + step * stepSize) % CAPACITY;
            if (state[index] == 1 && keys[index] == key) {
                return index;
            }
            if (state[index] == 2 && firstDeleted == -1) {
                firstDeleted = index;
            }
            if (state[index] == 0) {
                return firstDeleted == -1 ? index : firstDeleted;
            }
        }
        if (firstDeleted != -1) {
            return firstDeleted;
        }
        throw new IllegalStateException("hash table is full");
    }

    private int findExistingSlot(int key) {
        int hash = hash1(key);
        int stepSize = hash2(key);
        for (int step = 0; step < CAPACITY; step++) {
            int index = (hash + step * stepSize) % CAPACITY;
            if (state[index] == 0) {
                return -1;
            }
            if (state[index] == 1 && keys[index] == key) {
                return index;
            }
        }
        return -1;
    }

    private int hash1(int key) {
        return key % CAPACITY;
    }

    private int hash2(int key) {
        return 1 + key % (CAPACITY - 1);
    }
}
